                                                "illustration": {
                                                    "script": {
                                                        "apiVersion": "1.0.0",
                                                        "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.imports\n */\nfunction evaluateProperty({\n    api\n}) {\n    if (api.state.errorMessage) {\n        if (api.state.errorType) {\n            if (api.state.errorType == 'info_message') {\n                return 'first-time-user';\n            } else if (api.state.errorType == 'config_error') {\n                return 'unconfigured';\n            } else if (api.state.errorType == 'missing_field') {\n                return 'error';\n            }\n        }\n    } else if (api.state.newRiskEventId != -1) {\n        return 'completed-tasks';\n    }\n}"
                                                    },
                                                    "type": "CLIENT_TRANSFORM_SCRIPT"
                                                },
